return scope === 'project'
        ? { configPath: join(repoRoot, '.mcp.json'), format: 'json-mcpServers' }
        : { configPath: '<claude mcp add -s user>', format: 'claude-cli' };

return scope === 'project'
        ? { configPath: join(repoRoot, '.cursor', 'mcp.json'), format: 'json-mcpServers' }
        : { configPath: join(home, '.cursor', 'mcp.json'), format: 'json-mcpServers' };

return scope === 'project'
        ? { configPath: join(repoRoot, '.vscode', 'mcp.json'), format: 'json-servers' }
        : null;

return scope === 'project'
        ? { configPath: join(repoRoot, '.codex', 'config.toml'), format: 'toml' }
        : { configPath: join(home, '.codex', 'config.toml'), format: 'toml' };

return scope === 'global'
        ? {
            configPath: join(home, '.codeium', 'windsurf', 'mcp_config.json'),
            format: 'json-mcpServers',
          }
        : null;

return scope === 'project'
        ? { configPath: join(repoRoot, '.gemini', 'settings.json'), format: 'json-mcpServers' }
        : { configPath: join(home, '.gemini', 'settings.json'), format: 'json-mcpServers' };

out.push({
        ide,
        scope,
        configPath: '',
        written: false,
        command: bin,
        args: [],
        note: `${ide} does not support ${scope}-scope MCP config (upstream); skipping.`,
      });

out.push({
          ide,
          scope,
          configPath: target.configPath,
          written: false,
          command: bin,
          args,
          note: 'claude CLI not found on PATH; install Claude Code, or use project-scope `crib mcp install --ide claude`.',
        });

const block = [
        TOML_BEGIN,
        `[mcp_servers.${SERVER_NAME}]`,
        `command = ${tomlString(bin)}`,
        // Each arg is a TOML basic string → backslash- AND quote-escaped via tomlString. The earlier
        // form only quote-escaped (`a.replace(/"/g, '\\"')`), so a win32 absolute repo path like
        // `C:\Users\runneradmin\repo` serialized as `args = ["serve", "C:\Users\…\repo"]` with RAW
        // backslashes — invalid TOML (`\U`/`\C` are undefined escapes a parser rejects). Routing
        // args through tomlString matches the command-line escaping and yields valid TOML on win32.
        `args = [${args.map((a) => tomlString(a)).join(', ')}]`,
        'startup_timeout_sec = 20',
        'tool_timeout_sec = 60',
        TOML_END,
      ].join('\n');

out.push({
        ide,
        scope,
        configPath: '',
        written: false,
        command: '',
        args: [],
        note: `unsupported for ${ide}/${scope}`,
      });

out.push({
          ide,
          scope,
          configPath: target.configPath,
          written: true,
          command: '',
          args: [],
        });

out.push({
          ide,
          scope,
          configPath: target.configPath,
          written: false,
          command: '',
          args: [],
          note: 'claude CLI not found',
        });

out.push({
        ide,
        scope,
        configPath: target.configPath,
        written: false,
        command: '',
        args: [],
      });

out.push({
        ide,
        scope,
        configPath: target.configPath,
        written: updated !== existing,
        command: '',
        args: [],
      });

out.push({
        ide,
        scope,
        configPath: target.configPath,
        written: false,
        command: '',
        args: [],
      });

return {
      suppress: false,
      surfacedForReview: true,
      reason: `signal '${feedback.signal}' is not 'contradicted' — no suppression, bounded feedback only`,
    };

const decision: MemoryDecision = {
      id: decisionId({
        kind: 'quarantine',
        subject: record.id,
        actor,
        reason: QUARANTINE_REASON,
      }),
      schemaVersion: '1',
      kind: 'quarantine',
      subject: record.id,
      actor,
      reason: QUARANTINE_REASON,
      ts: now(),
    };

return {
    suppress: false,
    surfacedForReview: true,
    reason:
      'contradicted feedback without admissible+valid counter-evidence — bounded penalty applied, surfaced for review',
  };

const fbId = feedbackId({
    signal: input.feedback.signal,
    subject: input.feedback.subject,
    actor: input.feedback.actor,
    context: input.feedback.context,
  });

const feedback: MemoryFeedback = {
    id: fbId,
    schemaVersion: '1',
    signal: input.feedback.signal,
    subject: input.feedback.subject,
    actor: input.feedback.actor,
    ...(input.feedback.context ? { context: input.feedback.context } : {}),
    ts: input.now(),
    ...(input.feedback.meta ? { meta: input.feedback.meta } : {}),
  };

return {
    async readText() {
      return text;
    },
    treeSitter() {
      throw new Error('not used — Java is hand-rolled, no tree-sitter');
    },
    hash: contentHash,
    idFor: (kind: NodeKind, parts) => idFor({ kind, ...parts } as IdSpec),
  };

return (id: string): string => {
    const n = r.nodes.find((x) => x.id === id);
    // 1.3: `field` nodes carry a qualifiedName too (e.g. AuthController.service) — prefer it so the
    // member-of assertions stay readable; fall back to kind for file/route/explanation nodes.
    return n?.qualifiedName ?? n?.name ?? n?.kind ?? id;
  };
